-- Arbeitsrecht Berufsbildung > Pflichten von Arbeitgebern > Freistellung für Berufsschule Prüfungen (§ 15 BBiG)
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Muss ein Ausbildungsbetrieb einen Fachinformatiker für die Berufsschule freistellen?', 2, '[{"text": "Ja", "correct": true, "because": "§ 15 BBiG verpflichtet den Betrieb dazu"}, {"text": "Nein", "correct": false, "because": "Freistellung ist gesetzlich vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Betrieb einen Fachinformatiker während der Berufsschulzeit zur Arbeit verpflichten?', 2, '[{"text": "Nein", "correct": true, "because": "§ 15 BBiG fordert Freistellung für Berufsschule"}, {"text": "Ja", "correct": false, "because": "Berufsschule hat Vorrang"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein Ausbildungsbetrieb einen Fachinformatiker auch für IHK-Prüfungen freistellen?', 2, '[{"text": "Ja", "correct": true, "because": "§ 15 BBiG umfasst auch Prüfungen"}, {"text": "Nein", "correct": false, "because": "Prüfungen sind Teil der Freistellung"}]'),
('00000000-0000-0000-0000-000000000000', 'Darf ein Betrieb die Freistellung eines Fachinformatikers für Berufsschulprüfungen verweigern?', 2, '[{"text": "Nein", "correct": true, "because": "§ 15 BBiG schützt dieses Recht"}, {"text": "Ja", "correct": false, "because": "Verweigerung ist unzulässig"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein Fachinformatiker während der Freistellung für Berufsschulprüfungen weiterhin bezahlt werden?', 2, '[{"text": "Ja", "correct": true, "because": "§ 17 BBiG garantiert die Vergütung"}, {"text": "Nein", "correct": false, "because": "Vergütung bleibt erhalten"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche gesetzliche Grundlage verpflichtet einen Betrieb, einen Fachinformatiker für Berufsschulprüfungen freizustellen?', 2, '[{"text": "§ 15 BBiG", "correct": true, "because": "Regelt die Freistellung für Berufsschule und Prüfungen"}, {"text": "§ 13 BBiG", "correct": false, "because": "Bezieht sich auf Pflichten des Auszubildenden"}, {"text": "§ 17 BBiG", "correct": false, "because": "Regelt die Vergütung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was muss ein Ausbildungsbetrieb tun, wenn ein Fachinformatiker an Berufsschulprüfungen teilnimmt?', 3, '[{"text": "Ihn für die Prüfungszeit freistellen", "correct": true, "because": "§ 15 BBiG schreibt dies vor"}, {"text": "Ihn zur Arbeit verpflichten", "correct": false, "because": "Widerspricht der Freistellung"}, {"text": "Seine Vergütung kürzen", "correct": false, "because": "Nicht zulässig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer ist verpflichtet, einen Fachinformatiker für Berufsschulprüfungen freizustellen?', 2, '[{"text": "Der Ausbildungsbetrieb", "correct": true, "because": "§ 15 BBiG legt dies fest"}, {"text": "Die IHK", "correct": false, "because": "IHK überwacht nur"}, {"text": "Die Berufsschule", "correct": false, "because": "Schule hat keine Freistellungspflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert, wenn ein Betrieb einen Fachinformatiker nicht für Berufsschulprüfungen freistellt?', 3, '[{"text": "Die IHK kann einschreiten", "correct": true, "because": "IHK überwacht die Einhaltung von § 15 BBiG"}, {"text": "Der Auszubildende muss selbst kündigen", "correct": false, "because": "Nicht erforderlich"}, {"text": "Nichts passiert", "correct": false, "because": "Verstoß hat Konsequenzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Art von Prüfung rechtfertigt die Freistellung eines Fachinformatikers?', 3, '[{"text": "IHK-Abschlussprüfung", "correct": true, "because": "§ 15 BBiG umfasst berufsbezogene Prüfungen"}, {"text": "Private Zertifizierungen", "correct": false, "because": "Nicht vorgeschrieben"}, {"text": "Sportprüfung", "correct": false, "because": "Nicht berufsbezogen"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Veranstaltungen erfordern die Freistellung eines Fachinformatikers gemäß § 15 BBiG?', 4, '[{"text": "Berufsschulunterricht", "correct": true, "because": "Pflicht gemäß § 15 BBiG"}, {"text": "IHK-Zwischenprüfung", "correct": true, "because": "Teil der Ausbildung"}, {"text": "Private Schulungen", "correct": false, "because": "Nicht vorgeschrieben"}, {"text": "IHK-Abschlussprüfung", "correct": true, "because": "Berufsbezogene Prüfung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was muss ein Ausbildungsbetrieb bei der Freistellung eines Fachinformatikers für Berufsschulprüfungen beachten?', 3, '[{"text": "Freistellung für die gesamte Prüfungszeit", "correct": true, "because": "§ 15 BBiG fordert dies"}, {"text": "Fortzahlung der Vergütung", "correct": true, "because": "§ 17 BBiG schützt den Anspruch"}, {"text": "Arbeitsverpflichtung während der Prüfung", "correct": false, "because": "Widerspricht der Freistellung"}, {"text": "Benachrichtigung der IHK", "correct": false, "because": "Nicht erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenzen drohen einem Betrieb, der einen Fachinformatiker nicht für Berufsschulprüfungen freistellt?', 4, '[{"text": "Verwarnung durch die IHK", "correct": true, "because": "IHK überwacht § 15 BBiG"}, {"text": "Schadensersatzforderungen", "correct": true, "because": "Bei Nachweis möglich"}, {"text": "Automatische Schließung", "correct": false, "because": "Nicht vorgesehen"}, {"text": "Verlust der Ausbildungsberechtigung", "correct": true, "because": "Bei schwerem Verstoß möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rechte hat ein Fachinformatiker bei der Freistellung für Berufsschulprüfungen?', 3, '[{"text": "Freistellung für Prüfungszeiten", "correct": true, "because": "§ 15 BBiG garantiert dies"}, {"text": "Fortzahlung der Vergütung", "correct": true, "because": "§ 17 BBiG schützt den Anspruch"}, {"text": "Zusätzliche Urlaubstage", "correct": false, "because": "Nicht vorgesehen"}, {"text": "Befreiung von anderen Pflichten", "correct": true, "because": "Fokus auf Prüfung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was darf ein Betrieb während der Freistellung eines Fachinformatikers für Berufsschulprüfungen nicht tun?', 3, '[{"text": "Arbeit während der Prüfungszeit verlangen", "correct": true, "because": "Widerspricht § 15 BBiG"}, {"text": "Vergütung kürzen", "correct": true, "because": "§ 17 BBiG verbietet dies"}, {"text": "Freistellung gewähren", "correct": false, "because": "Das ist Pflicht"}, {"text": "IHK informieren", "correct": false, "because": "Nicht verboten"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Ein Betrieb muss einen Fachinformatiker für Berufsschulprüfungen freistellen. b) Die Vergütung kann während der Freistellung gekürzt werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Freistellung Pflicht, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) § 15 BBiG fordert Freistellung für IHK-Prüfungen. b) Der Betrieb kann die Freistellung verweigern.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Freistellung Pflicht, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Fachinformatiker bleibt während der Freistellung bezahlt. b) Freistellung gilt nur für Berufsschulunterricht.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Vergütung bleibt, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Ein Betrieb muss einen Fachinformatiker für die Zwischenprüfung freistellen. b) Die Freistellung gilt nur in der Probezeit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zwischenprüfung inbegriffen, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Freistellung für Berufsschulprüfungen ist ein Recht des Fachinformatikers. b) Der Betrieb kann während der Freistellung Arbeitsaufgaben anordnen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Freistellung Recht, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

